  c=(c===null||c===undefined)?'':''+c;
  return /(^|;\s*)(SUBP|SSOLoginState)=/.test(c) && /(^|;\s*)SUB=[^;]+/.test(c);
}
var ck='', snap='';
try{
  var lh=source.getLoginHeader();
  if(lh){ var hm=JSON.parse(''+lh); if(hm&&(hm.Cookie||hm.cookie)) snap=''+(hm.Cookie||hm.cookie); }
}catch(e){}
var cm='', cw='';
try{ cm=''+(cookie.getCookie('https://m.weibo.cn')||''); }catch(e){ cm=''; }
try{ cw=''+(cookie.getCookie('https://weibo.com')||''); }catch(e){ cw=''; }
if(_hLogin(cm)) ck=cm;
else if(_hLogin(cw)) ck=cw;
else if(_hLogin(snap)) ck=snap;
else ck=cm||cw||snap;
if(ck) h.Cookie=ck;
