    }));
  }catch(e){}
}

/* ---------- 博主：一个作者 = 一本书（目录为他全部微博）---------- */
function addUser(u,extra){
  try{
    if(!u) return;
    if(MODE!=='user') return;                              /* 只有博主源收人 */
    var id=u.id||u.idstr||''; if(!id) return;
    var name=clean(u.screen_name); if(!name) return;
    id=S(id); if(seenU[id]) return; seenU[id]=1;
    var intro=clean(u.description||'');
    var e=clean(extra||'');
    if(!intro&&e) intro=e;
    var meta=[];
    if(u.followers_count!=null) meta.push('粉丝 '+u.followers_count);
    if(u.statuses_count!=null) meta.push('微博 '+u.statuses_count);
    var s=intro;
    if(meta.length) s=(s?s+'　':'')+meta.join(' ｜ ');
    out.push(JSON.stringify({
      __t:'user', id:id, name:name,
      author:'博主',              /* 搜索列表靠这一列区分：微博看博主名、博主看“博主”、超话看“超话” */
      cover:avatar(u),
      intro:s
    }));
  }catch(e){}
}

/* ---------- 提示卡：登录失效 / 本页为空时给个明确说法 ---------- */
function addTip(msg,detail){
  out.push(JSON.stringify({
    __t:'tip', id:'', name:'⚠ '+S(msg), author:'提示', cover:'', intro:S(detail||'')
  }));
}

/* ================= 「我的」通道：收藏 / 点赞 / 我的微博 =================
   weibo.com/ajax 系列接口，必须带登录 Cookie。
   Cookie 来源：优先 weibo.com 域；没有就借用 m.weibo.cn 的 SUB（同一个 SSO 会话，值通用）。*/
function mineList(bu){
  var pg=1, mm=null;
  try{ mm=bu.match(/[?&]page=(\d+)/); }catch(e){ mm=null; }
  if(mm) pg=parseInt(mm[1],10)||1;
  var mt2=null; try{ mt2=bu.match(/[?&]mine=([a-z]+)/); }catch(e){ mt2=null; }
  var kind=mt2?mt2[1]:'';
  var onlyRepost=(kind==='repost')||bu.indexOf('only_repost=1')>-1;
  var target='';
  if(kind==='fav') target='https://weibo.com/ajax/favorites/all_fav?page='+pg;
  else if(kind==='like') target='https://weibo.com/ajax/statuses/likelist?page='+pg;
  else if(kind==='blog') target='https://weibo.com/ajax/statuses/mymblog?page='+pg+'&feature=0';
  else if(kind==='orig') target='https://weibo.com/ajax/statuses/mymblog?page='+pg+'&feature=1';
  else if(kind==='repost') target='https://weibo.com/ajax/statuses/mymblog?page='+pg+'&feature=0';
  else target=bu.replace(/[?&]only_repost=1/g,'');
  var uid='', mu=null;
  try{ mu=bu.match(/[?&]uid=(\d+)/); }catch(e){ mu=null; }
  if(mu) uid=mu[1];

  /* 只判断登录态，不再自己拼 Cookie 头（header 已统一注入，避免游客 SUB 覆盖登录态） */
  var ck='';
  try{
    var cm=S(cookie.getCookie('https://m.weibo.cn'));
    var cw=S(cookie.getCookie('https://weibo.com'));
    if(/(^|;\s*)(SUBP|SSOLoginState)=/.test(cm)) ck=cm;
    else if(/(^|;\s*)(SUBP|SSOLoginState)=/.test(cw)) ck=cw;
    else ck=cm||cw;
  }catch(e){ ck=''; }
  var hasLogin=/(^|;\s*)(SUBP|SSOLoginState)=/.test(ck);

  function getJson(u){
    var t='';
    try{
      var c=java.connect(u);
      c.header('Referer','https://weibo.com/');
      c.header('X-Requested-With','XMLHttpRequest');
      c.header('Accept','application/json, text/plain, */*');
      t=S(c.get().body());
    }catch(e1){
      try{ t=S(java.ajax(u)); }catch(e2){ t=''; }
    }
    return PJ(t);
  }

  if(!uid){
    var cf=getJson('https://m.weibo.cn/api/config');
    if(cf&&cf.data&&cf.data.uid) uid=S(cf.data.uid);
  }

  var real=target;
  if(uid&&real.indexOf('uid=')<0) real+=(real.indexOf('?')>-1?'&':'?')+'uid='+uid;

  var d=getJson(real);
  var arr=[], dd=d?(d.data||d):null;
  if(dd){
    if(Array.isArray(dd)) arr=dd;
    else if(Array.isArray(dd.list)) arr=dd.list;
    else if(Array.isArray(dd.statuses)) arr=dd.statuses;
    else if(Array.isArray(dd.favorites)) arr=dd.favorites;
    else if(Array.isArray(dd.cards)){
      for(var ci=0;ci<dd.cards.length;ci++){ var cc=dd.cards[ci]; if(cc&&cc.mblog) arr.push(cc.mblog); }
    }
  }

  var ok=S(d&&d.ok!==undefined?d.ok:'');
  if(!d||ok==='0'){
    if(pg<=1){
      var msg=clean((d&&(d.message||d.msg||d.error))||'');
      addTip(hasLogin?'接口拒绝了请求，Cookie 可能已失效':'未检测到微博登录',
        (msg?('微博返回：'+msg.slice(0,40)+'。'):'')+'请点右上角「登录」扫码，或到书源设置里登录微博后重试。');
    }
    return;
  }

  var list=[];
  for(var k=0;k<arr.length;k++){
    var it=arr[k];
    if(!it) continue;
    if(!it.id&&!it.idstr&&it.status&&it.status.id) it=it.status;
    if(!it.id&&!it.idstr&&!it.mid) continue;
    if(onlyRepost&&!it.retweeted_status) continue;
    list.push(it);
  }

  if(!list.length){
    if(pg<=1){
      if(onlyRepost) addTip('本页没有转发内容','微博的「转发」是混在全部微博里的，这一页恰好没有。可以下拉试下一页，或先看「我的微博」。');
      else addTip('这里还没有内容','接口返回正常（已登录），但这一页是空的。');
    }
    return;
  }

  for(var q=0;q<list.length;q++){ addMblog(list[q]); }
}

var bu='';
try{ bu=S(baseUrl); }catch(e){ bu=''; }
var mt=null; try{ mt=bu.match(/[?&]mine=([a-z]+)/); }catch(e){ mt=null; }
var isMine=(mt!==null)||bu.indexOf('weibo.com/ajax/')>-1;

if(isMine){
  mineList(bu);
}else{

var dt=root.data||{};
var info=dt.cardlistInfo||{};
var cid=S(info.containerid||'');

/* 超话信息流：整个超话 = 一本书 */
if(cid.indexOf('100808')===0){
  var title=clean(info.title_sub||(dt.pageInfo&&dt.pageInfo.title)||'超话');
  out.push(JSON.stringify({__t:'topic', id:cid, name:title||'超话', author:'超话', cover:'', intro:'超话：'+(title||'')}));
}else{
  /* 递归摘出所有微博卡与人卡，微博排前面、博主排后面 */
  var mblogs=[], users=[];
  var walk=function(node,depth){
    if(!node||typeof node!=='object'||depth>7) return;
    if(node.title&&/^广告$/.test(clean(node.title.text||''))) return;   /* 整张卡是广告位 */
    if(Array.isArray(node)){ for(var i=0;i<node.length;i++){ try{ walk(node[i],depth+1); }catch(e){} } return; }
    if(node.mblog) mblogs.push(node.mblog);
    if(node.user&&node.user.screen_name) users.push(node.user);
    for(var k in node){
      if(k==='retweeted_status'||k==='mblog'||k==='user'||k==='userInfo') continue;
      var v=node[k];
      if(v&&typeof v==='object'){ try{ walk(v,depth+1); }catch(e){} }
    }
  };
  try{ walk(dt.cards||[],0); }catch(e){}

  for(var i=0;i<mblogs.length;i++){ addMblog(mblogs[i]); if(mblogs[i]&&mblogs[i].user) users.push(mblogs[i].user); }
  for(var j=0;j<users.length;j++){ addUser(users[j],''); }

  /* 再走一次「用户搜索」通道：综合页一页只有 10 条左右微博，
     常常只落在一两个博主身上，这条通道一次能补十几个账号。*/
  var kw='';
  try{ kw=S(key); }catch(e){ kw=''; }
  var enc=kw;
  try{ enc=encodeURIComponent(kw); }catch(e){ enc=kw; }
  if(kw){
    var us='https://m.weibo.cn/api/container/getIndex?containerid=100103type%3D3%26q%3D'+enc+'&page_type=searchall&page=1';
    var r2=null;
    try{ r2=PJ(java.ajax(us)); }catch(e){ r2=null; }
    if(r2&&r2.data){
      try{
        var u2=[];
        var walk2=function(node,depth){
          if(!node||typeof node!=='object'||depth>7) return;
          if(Array.isArray(node)){ for(var a=0;a<node.length;a++){ try{ walk2(node[a],depth+1); }catch(e){} } return; }
          if(node.user&&node.user.screen_name) u2.push(node.user);
          for(var k2 in node){
            if(k2==='retweeted_status'||k2==='user'||k2==='userInfo') continue;
            var v2=node[k2];
            if(v2&&typeof v2==='object'){ try{ walk2(v2,depth+1); }catch(e){} }
          }
        };
        walk2(r2.data,0);
        for(var q=0;q<u2.length;q++){ addUser(u2[q],''); }
      }catch(e){}
    }
  }
}

}
out;

