ruleToc.chapterList:
@js:
function S(x){ if(x===null||x===undefined) return ''; try{ return ''+x; }catch(e){ return ''; } }
function PJ(x){ try{ return JSON.parse(S(x)); }catch(e){ return null; } }
var bookUrl='';
try{ if(typeof book!=='undefined' && book && book.bookUrl) bookUrl=S(book.bookUrl); }catch(e){}
var bookName='';
try{ if(typeof book!=='undefined' && book && book.name) bookName=S(book.name); }catch(e){}
var reqUrl=bookUrl;
try{ if(typeof baseUrl!=='undefined' && baseUrl) reqUrl=S(baseUrl); }catch(e){}
var raw='';
try{ raw=S(result); }catch(e){ raw=''; }

/* 每次重新拉目录都从第 1 页重新计数，避免旧计数把目录截断 */
try{
  if(typeof book!=='undefined' && book && book.variableMap){
    if(reqUrl.indexOf('since_id=')<0){
      book.variableMap.put('wbaTocPage','0');
      book.variableMap.put('wbaTocSince','');
      book.variableMap.put('wbaTocStop','');
      book.variableMap.put('wbaTocBase','0');
      book.variableMap.put('wbaTocLastCnt','0');
    }
  }
}catch(e){}
/* 章节序号跨页连续：wbaTocBase 是前面各页已经生成的正文条数，
   本页从 tocBase+1 接着编，翻页时由 nextTocUrl 把 base 推到下一页起点。*/
var tocBase=0;
try{
  if(typeof book!=='undefined' && book && book.variableMap){
    tocBase=parseInt(S(book.variableMap.get('wbaTocBase'))||'0',10)||0;
  }
}catch(e){ tocBase=0; }
var pageCnt=0;
function P(t){ try{ return JSON.parse(t); }catch(e){ return null; } }
function AJ(u){ try{ var r=java.ajax(u); return r?P(r):null; }catch(e){ return null; } }
/* 评论章节开关：书源编辑 → 右上角菜单 → 设置源变量，comments=0 关闭 */
var WANT_CMT=true;
try{
  if(typeof source!=='undefined' && source && source.getVariable){
    var sv=S(source.getVariable());
    if(/comments\s*=\s*0/i.test(sv)) WANT_CMT=false;
  }
}catch(e){ WANT_CMT=true; }

/* ===== 单条微博：正文 + 评论，两章 ===== */
if(bookUrl.indexOf('/api/config')>-1){
  [JSON.stringify({name:'请先登录微博：点书源右上角三点 →「登录」，可网页登录或粘贴 Cookie',url:bookUrl})];
}else if(bookUrl.indexOf('statuses/show')>-1){
  var sid=(bookUrl.match(/[?&]id=([0-9]+)/)||[])[1]||'';
  var a1=[];
  a1.push(JSON.stringify({name:'微博正文',url:bookUrl}));
  if(sid&&WANT_CMT) a1.push(JSON.stringify({name:'评论',url:'https://m.weibo.cn/api/comments/show?id='+sid+'&page=1'}));
  a1;
}else{

var uid=(bookUrl.match(/[?&]value=([0-9]+)/)||[])[1]||'';
var arr=[]; var seen={}; var route='';
function clean(t){ return S(t==null?'':t).replace(/<[^>]+>/g,'').replace(/\s+/g,' ').trim(); }
function pushMb(mb,onlyUid){
  if(!mb) return;
  var id=mb.idstr||mb.id; if(!id) return;
  id=S(id); if(seen[id]) return;
  if(onlyUid){
    var mu=S((mb.user&&(mb.user.id||mb.user.idstr))||'');
    if(mu!==onlyUid) return;
  }
  seen[id]=1;
  pageCnt++;
  var n=tocBase+pageCnt;
  var t=clean((mb.longText&&mb.longText.longTextContent)||mb.text||'').slice(0,16);
  arr.push(JSON.stringify({name:'正文'+n+(t?('·'+t):''),url:'https://m.weibo.cn/api/statuses/show?id='+id}));
  if(WANT_CMT) arr.push(JSON.stringify({name:'评论'+n,url:'https://m.weibo.cn/api/comments/show?id='+id+'&page=1'}));
}
function walk(node,depth,onlyUid){
  if(!node||typeof node!=='object'||depth>8) return;
  if(Array.isArray(node)){ for(var i=0;i<node.length;i++){ walk(node[i],depth+1,onlyUid); } return; }
  for(var k in node){
    if(k==='retweeted_status'||k==='user') continue;
    var v=node[k];
    if(v&&typeof v==='object'){
      if(k==='mblog'){ pushMb(v,onlyUid); continue; }
      walk(v,depth+1,onlyUid);
    }
  }
}

/* 路线1：Legado 已经取回的 result */
var r1=P(raw);
if(r1&&r1.data){ walk(r1,0,''); if(arr.length) route='result'; }
/* 路线2：自己带 Cookie 请求当前目录地址（翻页时带 since_id） */
if(!arr.length){ var r2=AJ(reqUrl); if(r2&&r2.data){ walk(r2,0,''); if(arr.length) route='ajax'; } }
/* 路线3：翻页失败时退回书籍原始地址 */
if(!arr.length&&reqUrl!==bookUrl){ var r3=AJ(bookUrl); if(r3&&r3.data){ walk(r3,0,''); if(arr.length) route='ajax-book'; } }
/* 路线4：按作者名搜一遍，只收该作者(UID)的微博 */
if(!arr.length&&uid&&bookName){
  try{
    var qn=''; try{ qn=encodeURIComponent(bookName); }catch(e){ qn=bookName; }
    var su='https://m.weibo.cn/api/container/getIndex?containerid=100103type%3D1%26q%3D'+qn+'&page_type=searchall&page=1';
    var r4=AJ(su);
    if(r4&&r4.data){ walk(r4,0,uid); if(arr.length) route='search'; }
  }catch(e){}
}
/* 路线5：旧版字段 statuses / list */
if(!arr.length&&r1&&r1.data){
  var cands=[r1.data.statuses,r1.data.list];
  for(var ci=0;ci<cands.length;ci++){ if(Array.isArray(cands[ci])){ for(var cj=0;cj<cands[ci].length;cj++){ pushMb(cands[ci][cj],''); } } }
  if(arr.length) route='data-list';
}

if(!arr.length){
  /* 翻页到底：静默返回空列表，让 Legado 正常收尾 */
  if(reqUrl!==bookUrl && reqUrl.indexOf('since_id=')>-1){
    try{ if(typeof book!=='undefined' && book && book.variableMap){ book.variableMap.put('wbaTocStop','1'); } }catch(e){}
    [];
  }
  else{
    var cn=(r1&&r1.data&&r1.data.cards)?r1.data.cards.length:-1;
    var hint='';
    if(!r1) hint='接口没响应，检查网络后再试';
    else if(r1.ok===0) hint='微博返回错误'+(r1.msg?('：'+S(r1.msg).slice(0,24)):'');
    else if(S(raw).indexOf('<html')>-1||S(raw).indexOf('<!DOCTYPE')>-1) hint='返回的是网页不是数据，需要登录';
    else if(cn===0) hint='这个账号没有公开微博';
    else if(cn>0) hint='这个账号只有资料卡没有微博（已封禁 / 注销 / 清空 / 仅半年可见）';
    else hint='这段内容里没有微博';
    arr.push(JSON.stringify({name:hint+' · 点我重试',url:bookUrl}));
  }
}
/* 把本页正文条数交给 nextTocUrl，翻页成功后 base 累加，序号才不会每页从 1 重来 */
try{
  if(typeof book!=='undefined' && book && book.variableMap){
    book.variableMap.put('wbaTocLastCnt', S(pageCnt));
  }
}catch(e){}
arr;
}

