function isVideo(mb){
  try{
    var pi=(mb&&mb.page_info)||{};
    if(S(pi.type)==='video'||S(pi.object_type)==='video') return true;
    if(pi.media_info&&/video/i.test(S(pi.media_info.media_type||''))) return true;
    var mm=(mb&&mb.mix_media_info)||{};
    if(S(mm.type)==='video') return true;
    var ps=(mb&&mb.pics)||[];
    for(var vi=0;vi<ps.length;vi++){ if(S(ps[vi].type)==='video') return true; }
  }catch(e){}
  return false;
}
function clean(t){ return S(t==null?'':t).replace(/<[^>]+>/g,'').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'\"').replace(/&#39;/g,"'").replace(/\s+/g,' ').trim(); }
function avatar(u){
  var a=S(u.avatar_hd||u.avatar_large||u.profile_image_url||u.avatar||'');
  if(a.indexOf('//')===0) a='https:'+a;
  return a;
}

/* ---------- 微博：一条微博 = 一本书 ---------- */
function addMblog(mb){
  try{
    if(!mb) return;
    if(mb.ad_state===1||mb.is_ad===1) return;                       /* 广告位 */
    if(mb.promotion&&(mb.promotion.promotion_id||mb.promotion.probe_id||mb.promotion.type)) return;
    if(MODE==='user') return;                              /* 博主源：一条微博都不收 */
    if(MODE==='pic'&&isVideo(mb)) return;                  /* 图文源：视频留给视频源 */
    if(MODE==='video'&&!isVideo(mb)) return;               /* 视频源：只要视频 */
    var id=S(mb.idstr||mb.id||mb.mid||''); if(!id||seenM[id]) return; seenM[id]=1;
    var t=clean((mb.longText&&mb.longText.longTextContent)||mb.text_raw||mb.text||'');
    var cover='';
    if(mb.pics&&mb.pics[0]&&mb.pics[0].large) cover=S(mb.pics[0].large.url);
    if(!cover&&mb.pic_ids&&mb.pic_ids[0]){
      var pid=S(mb.pic_ids[0]);
      var pi=(mb.pic_infos&&mb.pic_infos[pid])||null;
      if(pi&&pi.large&&pi.large.url) cover=S(pi.large.url);
      else cover='https://wx4.sinaimg.cn/large/'+pid+'.jpg';
    }
    if(!cover&&mb.url_objects&&mb.url_objects[0]&&mb.url_objects[0].object&&mb.url_objects[0].object.object&&mb.url_objects[0].object.object.image) cover=S(mb.url_objects[0].object.object.image.url);
    var ct=clean(mb.created_at||'');
    out.push(JSON.stringify({
      __t:'mblog', id:id,
      name:(t||'微博').slice(0,40),
      author:(mb.user&&mb.user.screen_name)||'',
      cover:cover,
      intro:(ct?ct+'　':'')+'转发 '+(mb.reposts_count||0)+' ｜ 评论 '+(mb.comments_count||0)+' ｜ 点赞 '+(mb.attitudes_count||0)
    }));
  }catch(e){}
}

/* ---------- 博主：一个作者 = 一本书（目录为他全部微博）---------- */
function addUser(u,extra){
  try{
    if(!u) return;
    if(MODE!=='user') return;                              /* 只有博主源收人 */
    var id=u.id||u.idstr||''; if(!id) return;
