@js:
function S(x){ if(x===null||x===undefined) return ''; try{ return ''+x; }catch(e){ return ''; } }
function PJ(x){ try{ return JSON.parse(S(x)); }catch(e){ return null; } }
var root={}; try{ root=PJ(result)||{}; }catch(e){ root={}; }
var out=[], seenM={}, seenU={};
var MODE='video';   /* pic=图文  video=视频  user=博主 */
function isVideo(mb){
  try{
    var pi=(mb&&mb.page_info)||{};
    if(S(pi.type)==='video'||S(pi.object_type)==='video') return true;
    if(pi.media_info&&/video/i.test(S(pi.media_info.media_type||''))) return true;
    var mm=(mb&&mb.mix_media_info)||{};
    if(S(mm.type)==='video') return true;
    var ps=(mb&&mb.pics)||[];
    for(var vi=0;vi<ps.length;vi++){ if(S(ps[vi].type)==='video') return true; }
  }catch(e){}
  return false;
}
var userCount=0, userCap=6;   /* 搜索里博主最多 6 个，顺序：发博人 > 用户搜索 > 推荐卡 */
function clean(t){ return S(t==null?'':t).replace(/<[^>]+>/g,'').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'\"').replace(/&#39;/g,"'").replace(/\s+/g,' ').trim(); }
function avatar(u){
  var a=S(u.avatar_hd||u.avatar_large||u.profile_image_url||u.avatar||'');
  if(a.indexOf('//')===0) a='https:'+a;
  return a;
}

/* ---------- 微博：一条微博 = 一本书 ---------- */
function addMblog(mb){
  try{
    if(!mb) return;
    if(mb.ad_state===1||mb.is_ad===1) return;                       /* 广告位 */
    if(mb.promotion&&(mb.promotion.promotion_id||mb.promotion.probe_id||mb.promotion.type)) return;
    if(MODE==='user') return;                              /* 博主源：一条微博都不收 */
    if(MODE==='pic'&&isVideo(mb)) return;                  /* 图文源：视频留给视频源 */
    if(MODE==='video'&&!isVideo(mb)) return;               /* 视频源：只要视频 */
    var id=S(mb.idstr||mb.id||mb.mid||''); if(!id||seenM[id]) return; seenM[id]=1;
    var t=clean((mb.longText&&mb.longText.longTextContent)||mb.text_raw||mb.text||'');
    var cover='';
    if(mb.pics&&mb.pics[0]&&mb.pics[0].large) cover=S(mb.pics[0].large.url);
    if(!cover&&mb.pic_ids&&mb.pic_ids[0]){
      var pid=S(mb.pic_ids[0]);
      var pi=(mb.pic_infos&&mb.pic_infos[pid])||null;
      if(pi&&pi.large&&pi.large.url) cover=S(pi.large.url);
      else cover='https://wx4.sinaimg.cn/large/'+pid+'.jpg';
    }
    if(!cover&&mb.url_objects&&mb.url_objects[0]&&mb.url_objects[0].object&&mb.url_objects[0].object.object&&mb.url_objects[0].object.object.image) cover=S(mb.url_objects[0].object.object.image.url);
    var ct=clean(mb.created_at||'');
    out.push(JSON.stringify({
      __t:'mblog', id:id,
      name:(t||'微博').slice(0,40),
      author:(mb.user&&mb.user.screen_name)||'',
      cover:cover,
      intro:(ct?ct+'　':'')+'转发 '+(mb.reposts_count||0)+' ｜ 评论 '+(mb.comments_count||0)+' ｜ 点赞 '+(mb.attitudes_count||0)
    }));
  }catch(e){}
}

/* ---------- 博主：一个作者 = 一本书（目录为他全部微博）---------- */
function addUser(u,extra){
  try{
    if(!u) return;
    if(MODE!=='user') return;                              /* 只有博主源收人 */
    if(userCount>=userCap) return;
    var id=u.id||u.idstr||''; if(!id) return;
    var name=clean(u.screen_name); if(!name) return;
    id=S(id); if(seenU[id]) return; seenU[id]=1;
    var intro=clean(u.description||'');
    var e=clean(extra||'');
    if(!intro&&e) intro=e;
    var meta=[];
    if(u.followers_count!=null) meta.push('粉丝 '+u.followers_count);
    if(u.statuses_count!=null) meta.push('微博 '+u.statuses_count);
    var s=intro;
    if(meta.length) s=(s?s+'　':'')+meta.join(' ｜ ');
    out.push(JSON.stringify({
      __t:'user', id:id, name:'【博主】'+name+((parseInt(S(u.statuses_count),10)===0)?'（无微博）':''),
      author:'博主',              /* 搜索列表靠这一列区分：微博看博主名、博主看“博主”、超话看“超话” */
      cover:avatar(u),
      intro:s
    }));
    userCount++;
  }catch(e){}
}

var dt=root.data||{};
var info=dt.cardlistInfo||{};
var cid=S(info.containerid||'');

/* 超话信息流：整个超话 = 一本书 */
if(cid.indexOf('100808')===0){
  var title=clean(info.title_sub||(dt.pageInfo&&dt.pageInfo.title)||'超话');
  out.push(JSON.stringify({__t:'topic', id:cid, name:title||'超话', author:'超话', cover:'', intro:'超话：'+(title||'')}));
}else{
  /* 递归摘出所有微博卡与人卡，微博排前面、博主排后面 */
  var mblogs=[], users=[];
  var walk=function(node,depth){
    if(!node||typeof node!=='object'||depth>7) return;
    if(node.title&&/^广告$/.test(clean(node.title.text||''))) return;   /* 整张卡是广告位 */
    if(Array.isArray(node)){ for(var i=0;i<node.length;i++){ try{ walk(node[i],depth+1); }catch(e){} } return; }
    if(node.mblog) mblogs.push(node.mblog);
    if(node.user&&node.user.screen_name) users.push(node.user);
    for(var k in node){
      if(k==='retweeted_status'||k==='mblog'||k==='user'||k==='userInfo') continue;
      var v=node[k];
      if(v&&typeof v==='object'){ try{ walk(v,depth+1); }catch(e){} }
    }
  };
  try{ walk(dt.cards||[],0); }catch(e){}

  for(var i=0;i<mblogs.length;i++){ addMblog(mblogs[i]); }
  /* 博主排序：1) 这批微博的发博人  2) 用户搜索命中的账号  3) 综合页里的推荐卡
     推荐卡相关性最弱，放到最后，免得把真正要搜的人挤掉。*/
  for(var i3=0;i3<mblogs.length;i3++){ if(mblogs[i3]&&mblogs[i3].user) addUser(mblogs[i3].user,''); }

  /* 再走一次「用户搜索」通道：综合页一页只有 10 条左右微博，
     常常只落在一两个博主身上，这条通道一次能补十几个账号。*/
  var kw='';
  try{ kw=S(key); }catch(e){ kw=''; }
  var enc=kw;
  try{ enc=encodeURIComponent(kw); }catch(e){ enc=kw; }
  if(kw&&userCount<userCap){
    var us='https://m.weibo.cn/api/container/getIndex?containerid=100103type%3D3%26q%3D'+enc+'&page_type=searchall&page=1';
    var r2=null;
    try{ r2=PJ(java.ajax(us)); }catch(e){ r2=null; }
    if(r2&&r2.data){
      try{
        var u2=[];
        var walk2=function(node,depth){
          if(!node||typeof node!=='object'||depth>7) return;
          if(Array.isArray(node)){ for(var a=0;a<node.length;a++){ try{ walk2(node[a],depth+1); }catch(e){} } return; }
          if(node.user&&node.user.screen_name) u2.push(node.user);
          for(var k2 in node){
            if(k2==='retweeted_status'||k2==='user'||k2==='userInfo') continue;
            var v2=node[k2];
            if(v2&&typeof v2==='object'){ try{ walk2(v2,depth+1); }catch(e){} }
          }
        };
        walk2(r2.data,0);
        for(var q=0;q<u2.length;q++){ addUser(u2[q],''); }
      }catch(e){}
    }
  }

  /* 名额还有剩，才拿综合页里的推荐账号来补 */
  for(var j=0;j<users.length;j++){ addUser(users[j],''); }
}
out;

