@js:
function S(x){ if(x===null||x===undefined) return ''; try{ return ''+x; }catch(e){ return ''; } }
function PJ(x){ try{ return JSON.parse(S(x)); }catch(e){ return null; } }
var bookUrl='';
try{ if(typeof book!=='undefined' && book && book.bookUrl) bookUrl=S(book.bookUrl); }catch(e){}
var bookName='';
try{ if(typeof book!=='undefined' && book && book.name) bookName=S(book.name); }catch(e){}
var reqUrl=bookUrl;
try{ if(typeof baseUrl!=='undefined' && baseUrl) reqUrl=S(baseUrl); }catch(e){}
var raw='';
try{ raw=S(result); }catch(e){ raw=''; }

/* 每次重新拉目录都从第 1 页重新计数，避免旧计数把目录截断 */
try{
  if(typeof book!=='undefined' && book && book.variableMap){
    if(reqUrl.indexOf('since_id=')<0){
      book.variableMap.put('wbaTocPage','0');
      book.variableMap.put('wbaTocSince','');
      book.variableMap.put('wbaTocStop','');
      book.variableMap.put('wbaTocBase','0');
      book.variableMap.put('wbaTocLastCnt','0');
    }
  }
}catch(e){}
/* 章节序号跨页连续：wbaTocBase 是前面各页已经生成的正文条数，
   本页从 tocBase+1 接着编，翻页时由 nextTocUrl 把 base 推到下一页起点。*/
var tocBase=0;
try{
  if(typeof book!=='undefined' && book && book.variableMap){
    tocBase=parseInt(S(book.variableMap.get('wbaTocBase'))||'0',10)||0;
  }
}catch(e){ tocBase=0; }
var pageCnt=0;
function P(t){ try{ return JSON.parse(t); }catch(e){ return null; } }
function AJ(u){ try{ var r=java.ajax(u); return r?P(r):null; }catch(e){ return null; } }
/* 评论章节开关：书源编辑 → 右上角菜单 → 设置源变量，comments=0 关闭 */
var WANT_CMT=true;
try{
