@js:
function S(x){ if(x===null||x===undefined) return ''; try{ return ''+x; }catch(e){ return ''; } }
function PJ(x){ try{ return JSON.parse(S(x)); }catch(e){ return null; } }

/* 目录最多翻几页。1 页≈12 条微博≈24 章。
   8 页≈100 条微博≈190 章，加载约 10 秒；
   想更全就调大（更快的话把 concurrentRate 调小），想更快就调小。*/
var MAXPAGE=8;

var url='';
try{ if(typeof book!=='undefined' && book && book.bookUrl) url=S(book.bookUrl); }catch(e){}
if(!url){ try{ url=S(baseUrl); }catch(e){} }
if(url.indexOf('statuses/show')>-1){ ''; }
else{
  var root={}; try{ root=PJ(result)||{}; }catch(e){ root={}; }
  var info=(root.data&&root.data.cardlistInfo)||{};
  var since=S(info.since_id);
  var page=0, lastSince='', stopAll=false;
  try{
    if(typeof book!=='undefined' && book && book.variableMap){
      page=parseInt(S(book.variableMap.get('wbaTocPage'))||'0',10)||0;
      lastSince=S(book.variableMap.get('wbaTocSince'));
      stopAll=S(book.variableMap.get('wbaTocStop'))==='1';
    }
  }catch(e){}

  var base=url.replace(/([?&])since_id=[^&]*/g,'').replace(/[?&]$/,'');

  /* 三种收尾：无游标 / 游标没变(微博末页会回同一值，会死循环) / 到页数上限 / 已判定到底 */
  if(!since || since===lastSince || stopAll || page>=MAXPAGE){ ''; }
  else{
    try{
      if(typeof book!=='undefined' && book && book.variableMap){
        book.variableMap.put('wbaTocPage',S(page+1));
        book.variableMap.put('wbaTocSince',since);
        /* 本页已生成 lastCnt 条正文，下一页的序号从 base+lastCnt+1 开始 */
        var lst=parseInt(S(book.variableMap.get('wbaTocLastCnt'))||'0',10)||0;
        var bse=parseInt(S(book.variableMap.get('wbaTocBase'))||'0',10)||0;
        if(lst>0) book.variableMap.put('wbaTocBase', S(bse+lst));
      }
    }catch(e){}
    base+(base.indexOf('?')>-1?'&':'?')+'since_id='+since;
  }
}

loginUrl:
@js:
/* ===== 微博登录 =====
   ① 网页登录：内置浏览器登录，Cookie 自动进 CookieJar
   ② 保存并验证：把输入框里的 Cookie 写入三个域，并立刻向微博确认
   ③ 验证登录状态：把现有 Cookie 逐个拿去问 /api/config
   ④ 导出 Cookie 到输入框：回填后重开本窗口即可长按复制
   ⑤ 退出登录
   ⑥ 评论章节开关
*/
function _wbS(x){ if(x===null||x===undefined) return ''; try{ return ''+x; }catch(e){ return ''; } }
function _wbTrim(c){
  return _wbS(c)
    .replace(/^\s*Cookie\s*:\s*/i,'')
    .replace(/[\r\n]+/g,' ')
    .replace(/\s*;\s*/g,'; ')
    .replace(/^\s+/,'').replace(/\s+$/,'');
}
/* 读登录表单输入框（Legado 把表单值以 Map 形式绑到 result） */
function _wbVal(k){
  var v='';
  try{ v=result.get(k); }catch(e){ try{ v=result[k]; }catch(e2){ v=''; } }
  return _wbTrim(v);
}
/* 写 CookieJar 三个域 + 登录信息（重开登录窗口时回填到输入框） */
function _wbStore(c, uid){
  c=_wbTrim(c); if(!c) return '';
  try{ cookie.setCookie('https://weibo.com', c); }catch(e){}
  try{ cookie.setCookie('https://m.weibo.cn', c); }catch(e){}
  try{ cookie.setCookie('https://passport.weibo.cn', c); }catch(e){}
  try{ java.putLoginInfo(JSON.stringify({Cookie:c, Uid:_wbS(uid||'')})); }catch(e){}
  return c;
}
/* 只有验证通过的 Cookie 才写「登录头」快照，避免游客 Cookie 顶掉登录态 */
function _wbSnapshot(c){
  c=_wbTrim(c); if(!c) return '';
  try{ java.putLoginHeader(JSON.stringify({Cookie:c})); }catch(e){}
  return c;
}
/* 带指定 Cookie 请求 /api/config。connect 第二个参数是 header 的 JSON，不能对返回值链式 header() */
function _wbCfg(c){
  var b='';
  try{ b=_wbS(java.connect('https://m.weibo.cn/api/config', JSON.stringify({Cookie:c})).body()); }
  catch(e){ return null; }
  try{ return JSON.parse(b); }catch(e){ return null; }
}
/* 收集现有 Cookie：CookieJar 两个域 / 登录头快照 / 登录信息 */
function _wbCands(){
  var list=[], seen={};
  function add(c){ c=_wbTrim(c); if(c&&!seen[c]){ seen[c]=1; list.push(c); } }
  try{ add(cookie.getCookie('https://m.weibo.cn')); }catch(e){}
  try{ add(cookie.getCookie('https://weibo.com')); }catch(e){}
  try{ var lh=java.getLoginHeader(); if(lh){ var m=JSON.parse(''+lh); if(m) add(m.Cookie||m.cookie||''); } }catch(e){}
  try{ var li=java.getLoginInfoMap(); if(li){ var v=''; try{ v=li.get('Cookie'); }catch(e){ v=li['Cookie']||''; } add(v); } }catch(e){}
  /* 登录态排前面：验证、导出都先撞上真正的登录 Cookie，别被游客 Cookie 抢了 */
  var good=[], badx=[];
  for(var i=0;i<list.length;i++){
    if(/(^|;\s*)(SUBP|SSOLoginState)=/.test(list[i])) good.push(list[i]);
    else badx.push(list[i]);
  }
  return good.concat(badx);
}
function _wbCheck(){
  var list=_wbCands();
  if(!list.length){
    java.toast('没有任何 Cookie。请点① 网页登录，或把 Cookie 粘到输入框后点②');
    return false;
  }
  for(var i=0;i<list.length;i++){
    var j=_wbCfg(list[i]);
    if(j&&j.data&&j.data.login){
      var uid=_wbS(j.data.uid||'');
      _wbStore(list[i], uid);
      _wbSnapshot(list[i]);
      java.toast('已登录 · UID '+uid+' · 用的第 '+(i+1)+' 份 Cookie，共 '+list[i].length+' 字符');
      return true;
    }
  }
  java.toast('未登录：现有 '+list.length+' 份 Cookie 微博都不认作登录态。请点① 网页登录（最省事），或确认粘的是浏览器里 weibo.com 登录后的完整 Cookie');
  return false;
}
/* 保存一条 Cookie：先问微博是不是登录态，是才写域 + 快照；
   不是就只留一份用于回填，绝不覆盖已有的登录状态。*/
function _wbApply(c){
  c=_wbTrim(c);
  if(!c){ java.toast('输入框是空的：先把 Cookie 粘进来，或直接点① 网页登录'); return ''; }
  var j=_wbCfg(c);
  if(j===null){ _wbStore(c,''); java.toast('网络异常，未能验证，已直接保存 Cookie'); return 'unverified'; }
  if(j&&j.data&&j.data.login){
    var uid=_wbS(j.data.uid||'');
    _wbStore(c, uid);
    _wbSnapshot(c);
    java.toast('已登录 · UID '+uid+' · Cookie '+c.length+' 字符，已保存');
    return 'ok';
  }
  try{ java.putLoginInfo(JSON.stringify({Cookie:c, Uid:''})); }catch(e){}
  java.toast('这份 Cookie 不是登录态（微博判定未登录），已保留现有登录不变。请确认复制的是浏览器里 weibo.com 登录后的完整 Cookie');
  return 'notlogin';
}
/* 尝试直接写系统剪贴板。书源 JS 沙箱本身没有剪贴板 API，
   这里走 Rhino 的 Packages 反射拿 Context，能拿到就直接复制，
拿不到返回 false 由上层降级。*/
function _wbClip(c){
  if(typeof Packages==='undefined') return false;
  var ctx=null;
  /* 依次尝试若干拿 Application Context 的入口，任何一个成功就够用 */
  try{ ctx=Packages.splitties.init.AppCtxKt.getAppCtx(); }catch(e){}
  if(!ctx){ try{ ctx=Packages.splitties.init.AppCtx.getCtx(); }catch(e){} }
  if(!ctx){ try{ ctx=Packages.splitties.init.AppCtx.INSTANCE.getCtx(); }catch(e){} }
  if(!ctx){ try{ ctx=Packages.android.app.ActivityThread.currentApplication(); }catch(e){} }
  if(!ctx){ try{ ctx=Packages.android.app.AppGlobals.getInitialApplication(); }catch(e){} }
  if(!ctx) return false;
  var cm=null;
  try{ cm=ctx.getSystemService('clipboard'); }catch(e){ cm=null; }
  if(!cm) return false;
  try{
    cm.setPrimaryClip(Packages.android.content.ClipData.newPlainText('Cookie', c));
    return true;
  }catch(e){ return false; }
}
/* 回填登录表单并回读校验，返回 ok / mismatch / empty / error */
function _wbPutInfo(c){
  try{
    java.putLoginInfo(JSON.stringify({Cookie:c, Uid:''}));
    var m=java.getLoginInfoMap();
    var back='';
    if(m){ try{ back=''+m.get('Cookie'); }catch(e){ back=''; } }
    if(back===c) return 'ok';
    return back?'mismatch':'empty';
  }catch(e){ return 'error'; }
}
/* 兜底：把 Cookie 写进源变量，书源编辑里能看能选中复制 */
function _wbPutVar(c){
  try{
    var sv=''; try{ sv=''+source.getVariable(); }catch(e){ sv=''; }
    var on=!/comments\s*=\s*0/i.test(sv);
    var lines=sv.split('\n'), out=[];
    out.push('comments='+(on?'1':'0'));
    for(var i=0;i<lines.length;i++){
      var ln=lines[i];
      if(!ln) continue;
      if(ln.indexOf('wb_cookie=')===0) continue;
      if(/^comments\s*=/.test(ln)) continue;
      out.push(ln);
    }
    out.push('wb_cookie='+c);
    source.setVariable(out.join('\n'));
    var chk=''; try{ chk=''+source.getVariable(); }catch(e){}
    return chk.indexOf('wb_cookie=')>-1?'ok':'fail';
  }catch(e){ return 'error'; }
}
/* 导出主流程：剪贴板 → 输入框回填 → 源变量，逐级降级 */
function _wbExport(c){
  c=_wbTrim(c);
  if(!c){ java.toast('当前没有 Cookie，先点① 网页登录'); return ''; }
  if(_wbClip(c)){ _wbPutInfo(c); java.toast('已复制到剪贴板（'+c.length+' 字符），可直接粘贴'); return 'clip'; }
  var ok=_wbPutInfo(c);
  if(ok==='ok'){ java.toast('已回填输入框（'+c.length+' 字符）：关掉本窗口重开「登录」，长按输入框全选复制'); return 'input'; }
  var pv=_wbPutVar(c);
  if(pv==='ok'){ java.toast('已写入书源变量（'+c.length+' 字符）：书源编辑 → 右上角三点 → 设置源变量，长按复制'); return 'var'; }
  java.toast('导出失败（clip=no info='+ok+' var='+pv+'）：请把这句话反馈一下');
  return 'fail';
}
function _wbToggleCmt(){
  var v=''; try{ v=_wbS(source.getVariable()); }catch(e){ v=''; }
  var on=!/comments\s*=\s*0/i.test(v);
  /* 只改 comments 行，导出的 wb_cookie 保留 */
  var lines=v.split('\n'), out=[], kept=[];
  for(var i=0;i<lines.length;i++){
    var ln=lines[i];
    if(!ln) continue;
    if(/^comments\s*=/.test(ln)) continue;
    kept.push(ln);
  }
  out.push('comments='+(on?'0':'1'));
  for(var j=0;j<kept.length;j++) out.push(kept[j]);
  try{ source.setVariable(out.join('\n')); }catch(e){}
  java.toast(on?'评论章节：已关闭 → 重新打开目录生效（再点一次可恢复）':'评论章节：已开启 → 重新打开目录生效（再点一次可关闭）');
}
/* 点表单“确定”时由 Legado 调用：只落 CookieJar，不写快照 */
function login(){
  var c='';
  try{ var m=java.getLoginInfoMap(); if(m){ try{ c=m.get('Cookie'); }catch(e){ c=m['Cookie']||''; } } }catch(e){}
  c=_wbTrim(c);
  if(c) _wbApply(c);
}

