@js:
/* 统一在这里注入 Cookie：
   1) CookieStore 里如果有「登录态」（含 SUBP / SSOLoginState）就用它，CookieJar 刷新后能自动跟上；
   2) 否则用登录时留的快照（loginHeader），防止微博返回游客 Set-Cookie 把登录态冲掉；
   3) 都没有才退回任意 Cookie（游客态，只能看公开内容）。*/
var h={"User-Agent":"Mozilla/5.0 (iPhone; CPU iPhone OS 16_6 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.6 Mobile/15E148 Safari/604.1","Accept":"application/json, text/plain, */*","Referer":"https://m.weibo.cn/"};
function _hLogin(c){
  c=(c===null||c===undefined)?'':''+c;
  return /(^|;\s*)(SUBP|SSOLoginState)=/.test(c) && /(^|;\s*)SUB=[^;]+/.test(c);
}
var ck='', snap='';
try{
  var lh=source.getLoginHeader();
  if(lh){ var hm=JSON.parse(''+lh); if(hm&&(hm.Cookie||hm.cookie)) snap=''+(hm.Cookie||hm.cookie); }
}catch(e){}
var cm='', cw='';
try{ cm=''+(cookie.getCookie('https://m.weibo.cn')||''); }catch(e){ cm=''; }
try{ cw=''+(cookie.getCookie('https://weibo.com')||''); }catch(e){ cw=''; }
if(_hLogin(cm)) ck=cm;
else if(_hLogin(cw)) ck=cw;
else if(_hLogin(snap)) ck=snap;
else ck=cm||cw||snap;
if(ck) h.Cookie=ck;
JSON.stringify(h);

