var out=[], seenM={}, seenU={};
var MODE='user';   /* pic=图文  video=视频  user=博主 */
function isVideo(mb){
  try{
    var pi=(mb&&mb.page_info)||{};
    if(S(pi.type)==='video'||S(pi.object_type)==='video') return true;
    if(pi.media_info&&/video/i.test(S(pi.media_info.media_type||''))) return true;
    var mm=(mb&&mb.mix_media_info)||{};
    if(S(mm.type)==='video') return true;
    var ps=(mb&&mb.pics)||[];
    for(var vi=0;vi<ps.length;vi++){ if(S(ps[vi].type)==='video') return true; }
  }catch(e){}
  return false;
}
function clean(t){ return S(t==null?'':t).replace(/<[^>]+>/g,'').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'\"').replace(/&#39;/g,"'").replace(/\s+/g,' ').trim(); }
