    }
  }
}

/* 路线1：Legado 已经取回的 result */
var r1=P(raw);
if(r1&&r1.data){ walk(r1,0,''); if(arr.length) route='result'; }
/* 路线2：自己带 Cookie 请求当前目录地址（翻页时带 since_id） */
if(!arr.length){ var r2=AJ(reqUrl); if(r2&&r2.data){ walk(r2,0,''); if(arr.length) route='ajax'; } }
/* 路线3：翻页失败时退回书籍原始地址 */
if(!arr.length&&reqUrl!==bookUrl){ var r3=AJ(bookUrl); if(r3&&r3.data){ walk(r3,0,''); if(arr.length) route='ajax-book'; } }
/* 路线4：按作者名搜一遍，只收该作者(UID)的微博 */
if(!arr.length&&uid&&bookName){
  try{
    var qn=''; try{ qn=encodeURIComponent(bookName); }catch(e){ qn=bookName; }
    var su='https://m.weibo.cn/api/container/getIndex?containerid=100103type%3D1%26q%3D'+qn+'&page_type=searchall&page=1';
    var r4=AJ(su);
    if(r4&&r4.data){ walk(r4,0,uid); if(arr.length) route='search'; }
  }catch(e){}
}
/* 路线5：旧版字段 statuses / list */
if(!arr.length&&r1&&r1.data){
  var cands=[r1.data.statuses,r1.data.list];
  for(var ci=0;ci<cands.length;ci++){ if(Array.isArray(cands[ci])){ for(var cj=0;cj<cands[ci].length;cj++){ pushMb(cands[ci][cj],''); } } }
  if(arr.length) route='data-list';
}

if(!arr.length){
  /* 翻页到底：静默返回空列表，让 Legado 正常收尾 */
  if(reqUrl!==bookUrl && reqUrl.indexOf('since_id=')>-1){
    try{ if(typeof book!=='undefined' && book && book.variableMap){ book.variableMap.put('wbaTocStop','1'); } }catch(e){}
    [];
  }
  else{
    var cn=(r1&&r1.data&&r1.data.cards)?r1.data.cards.length:-1;
    var hint='';
    if(!r1) hint='接口没响应，检查网络后再试';
    else if(r1.ok===0) hint='微博返回错误'+(r1.msg?('：'+S(r1.msg).slice(0,24)):'');
    else if(S(raw).indexOf('<html')>-1||S(raw).indexOf('<!DOCTYPE')>-1) hint='返回的是网页不是数据，需要登录';
    else if(cn===0) hint='这个账号没有公开微博';
    else if(cn>0) hint='这个账号只有资料卡没有微博（已封禁 / 注销 / 清空 / 仅半年可见）';
    else hint='这段内容里没有微博';
    arr.push(JSON.stringify({name:hint+' · 点我重试',url:bookUrl}));
  }
}
/* 把本页正文条数交给 nextTocUrl，翻页成功后 base 累加，序号才不会每页从 1 重来 */
try{
  if(typeof book!=='undefined' && book && book.variableMap){
    book.variableMap.put('wbaTocLastCnt', S(pageCnt));
  }
}catch(e){}
arr;
}

